import 'dart:typed_data';

import 'package:flutter/services.dart';
import 'package:geolocator/geolocator.dart';

const geoidAssetPath = "assets/geoid/egm96_0.5deg.bin";

/// EGM96 geoid height grid (generated by scripts/gen_geoid_grid.py).
///
/// int16 little-endian centimeters. Rows run 90N to 90S, columns run 0E eastward.
class GeoidGrid {
  final Int16List _data;
  final int rows;
  final int cols;
  final double step;

  GeoidGrid._(this._data, this.rows, this.cols, this.step);

  factory GeoidGrid.fromBytes(ByteData bytes) {
    final count = bytes.lengthInBytes ~/ 2;
    final data = Int16List(count);
    for (int i = 0; i < count; i++) {
      data[i] = bytes.getInt16(i * 2, Endian.little);
    }
    // rows = 180 / step + 1, cols = 360 / step  ->  count = cols * (cols / 2 + 1)
    int cols = 360;
    while (cols * (cols ~/ 2 + 1) < count) {
      cols *= 2;
    }
    if (cols * (cols ~/ 2 + 1) != count) {
      throw ArgumentError("Unexpected geoid grid size: ${bytes.lengthInBytes} bytes");
    }
    return GeoidGrid._(data, cols ~/ 2 + 1, cols, 360 / cols);
  }

  double _at(int row, int col) => _data[row * cols + col] / 100;

  /// Geoid height (meters) above the WGS84 ellipsoid. MSL = ellipsoid height - N.
  double height(double lat, double lon) {
    final y = ((90 - lat) / step).clamp(0.0, rows - 1.0);
    final x = (lon % 360) / step;
    final r0 = y.floor().clamp(0, rows - 2);
    final c0 = x.floor() % cols;
    final c1 = (c0 + 1) % cols;
    final fy = y - r0;
    final fx = x - x.floor();
    final top = _at(r0, c0) * (1 - fx) + _at(r0, c1) * fx;
    final bot = _at(r0 + 1, c0) * (1 - fx) + _at(r0 + 1, c1) * fx;
    return top * (1 - fy) + bot * fy;
  }
}

GeoidGrid? geoid;

Future initGeoid() async {
  geoid = GeoidGrid.fromBytes(await rootBundle.load(geoidAssetPath));
}

/// Android reports altitude above the WGS84 ellipsoid. Shift it to MSL to match iOS, NMEA, the DEM and airspaces.
/// Returns [position] unchanged if no grid is loaded or the fix has no altitude.
Position ellipsoidToMsl(Position position, {GeoidGrid? grid}) {
  grid ??= geoid;
  if (grid == null || !position.hasAltitude) return position;
  return Position.fromMap(
      {...position.toJson(), "altitude": position.altitude - grid.height(position.latitude, position.longitude)});
}
